# ── Path safety (SEC-001) ───────────────────────────────────
# safe_path <path>  →  realpath -m + contenção em ECC_HOME ou HOME
safe_path() {
    local p="$1"
    local r
    r=$(realpath -m -- "$p" 2>/dev/null) || die "Invalid path: $p"
    case "$r" in
        "$ECC_HOME"/*|"$HOME"/*) echo "$r" ;;
        *) die "Path escape attempt: $r" ;;
    esac
}

# ── Path safety (SEC-001) ───────────────────────────────────
